/**
 * @param string $primary   accepted primary: TH TF BS BP AS AD
 * @param string $language  'characters' | 'plain'
 */
function wr_build_report(array $answers, string $primary, string $language, ?string $secondarySelected = null, ?string $secondaryResponse = null): array
{
    if (!isset(WR_TITLES[$primary])) {
        throw new WellbeingScoringError('An accepted primary is required for the full report.');
    }
    $c = wr_content();
    $l = wr_launch();
    $plain = $language === 'plain';
    $support = wr_support_flags($answers);
    $secondary = wr_secondary_state($answers, $primary, $secondarySelected, $secondaryResponse);
    $paired = !$plain && $secondary['selection']['content'] === 'paired';
    $secondaryId = $paired ? $secondary['selection']['secondary'] : null;
    $question = $plain ? null : $secondary['question'];

    $q41 = array_values(array_filter(wp_choices($answers, '4.1'), static fn($v) => is_string($v) && isset(WR_COPING_LABELS[wr_letter($v)])));
    $q42 = wp_single($answers, '4.2');
    $time = wr_time_label($answers);
    $activity = wr_most_helpful_activity($answers);
    $activityEligible = $activity !== null && !($support['restricted'] && in_array($activity, ['6.5.b', '6.5.m'], true));

    $sections = [];

    // 1 How to read your report
    $sections[1] = array_merge(
        array_map('wr_p', $c['s1']['opening']),
        array_map('wr_p', $plain ? $c['s1']['plain'] : $c['s1']['characters']),
        array_map('wr_p', $c['s1']['support'])
    );

    // 2 Meet your crew / Understanding your responses
    $sections[2] = array_map('wr_p', $plain ? $c['s2']['plain'] : $c['s2']['characters']);

    // 3 When things get tough
    if ($plain) {
        $labels = array_map(static fn($id) => wr_quote(WR_COPING_LABELS[wr_letter($id)]), $q41);
        $sections[3] = [
            wr_p(str_replace('{q41}', wr_join($labels), $c['s3']['plain']['template'])),
            wr_p($c['s3']['plain']['follow']),
        ];
    } else {
        $block = $c['s3']['primary'][$primary];
        $sections[3] = [wr_h(WR_HEADINGS[$primary]), ...array_map('wr_p', $block['intro'])];
        foreach ($block['blocks'] as $b) {
            $sections[3][] = wr_h($b['heading']);
            array_push($sections[3], ...wr_items($b['items']));
        }
    }

    // 4 When it gets really hard
    if ($plain) {
        $sections[4] = [wr_p(str_replace('{q42}', wr_quote(WR_COPING_LABELS[wr_letter($q42)]), $c['s4']['plain']))];
    } elseif ($paired) {
        $block = $c['s4']['secondary'][$secondaryId];
        $sections[4] = [wr_h(WR_HEADINGS[$secondaryId]), ...array_map('wr_p', $block['intro'])];
        foreach ($block['blocks'] as $b) {
            $items = $b['items'];
            if ($support['restricted']) {
                if ($b['heading'] === 'What tends to help in those moments' && isset($c['restricted']['s4_help_' . $secondaryId])) {
                    $items[0] = $c['restricted']['s4_help_' . $secondaryId];
                }
                if ($b['heading'] === 'What happens' && $secondaryId === 'A') {
                    $items[0] = $c['restricted']['s4_happens_A'];
                }
            }
            $sections[4][] = wr_h($b['heading']);
            array_push($sections[4], ...wr_items($items));
        }
        $pair = $c['s4']['pairs'][$primary . '_' . $secondaryId];
        if ($support['restricted'] && $primary . '_' . $secondaryId === 'TF_A') {
            $last = 'If you decide that a repair is needed, choose a manageable and safe way to make it; direct contact with someone unsafe or unavailable is not required.';
            $pair = substr($pair, 0, -strlen($last)) . $c['restricted']['pair_TF_A_repair'];
        }
        $sections[4][] = wr_h('How ' . WR_SHORT[$primary] . ' and ' . WR_SHORT[$secondaryId] . ' may fit together');
        $sections[4][] = wr_p($pair);
    } else {
        $status = $secondary['selection']['status'];
        $key = $status === 'pending' ? 'pending' : (in_array($status, ['declined', 'unsure', 'skipped'], true) ? 'declined' : 'none');
        $sections[4] = [wr_p($c['s4']['transition'][$key])];
        if ($question !== null) {
            $sections[4][] = ['type' => 'question'];
        }
    }

    // 5 What's underneath
    $ratings = [];
    foreach ($c['s5']['statements'] as $qid => $_) {
        $ratings[$qid] = wp_scale($answers, $qid);
    }
    $s5 = [wr_p($c['s5']['opening'])];
    $high = array_keys(array_filter($ratings, static fn($r) => $r >= 3));
    if ($high !== []) {
        $s5[] = wr_p(str_replace('{list}', wr_join(array_map(static fn($q) => lcfirst($c['s5']['statements'][$q]['title']), $high)), $c['s5']['high_sentence']));
    }
    $rows = [];
    foreach ($c['s5']['statements'] as $qid => $s) {
        $rows[] = [$s['title'], $ratings[$qid] . ' — ' . $c['s5']['labels'][$ratings[$qid]]];
    }
    $s5[] = ['type' => 'table', 'head' => ['Statement area', 'Your rating'], 'rows' => $rows];
    foreach ($c['s5']['statements'] as $qid => $s) {
        $r = $ratings[$qid];
        if ($r < 2) {
            continue;
        }
        $level = $r >= 3 ? $s['high'] : $s['mid'];
        $s5[] = wr_h($level['title']);
        $s5[] = wr_note($s['statement']);
        foreach ($level['paras'] as $p) {
            $s5[] = wr_p(str_replace('[rating label]', wr_quote($c['s5']['labels'][$r]), $p));
        }
    }
    $zeros = array_keys(array_filter($ratings, static fn($r) => $r === 0));
    $ones = array_keys(array_filter($ratings, static fn($r) => $r === 1));
    if ($zeros !== [] || $ones !== []) {
        $s5[] = wr_h($c['s5']['less_heading']);
        if ($zeros !== []) {
            $s5[] = wr_p(str_replace('{list}', wr_join(array_map(static fn($q) => $c['s5']['statements'][$q]['fragment'], $zeros)), $c['s5']['zeros']));
        }
        if ($ones !== []) {
            $s5[] = wr_p(str_replace('{list}', wr_join(array_map(static fn($q) => $c['s5']['statements'][$q]['fragment'], $ones)), $c['s5']['ones']));
        }
    }
    $sections[5] = $s5;

    // 6 How you cope
    $q43 = wp_int($answers, '4.3', 0, 4);
    $scale = $q43 <= 1 ? 'towards the helpful end of the scale' : ($q43 === 2 ? 'the middle of the scale' : 'towards the end of the scale marked “it makes things worse”');
    $s6 = [
        wr_p(strtr($c['s6']['opening'], [
            '{q41}' => wr_join(array_map(static fn($id) => WR_COPING_PHRASES[wr_letter($id)], $q41)),
            '{q43}' => $q43 . ' out of 4, ' . $scale,
        ])),
        wr_p(str_replace('{q42}', WR_COPING_GERUNDS[wr_letter($q42)], $l['s6_context'])),
        wr_p($c['s6']['helpful'][$q43 <= 1 ? 'low' : ($q43 === 2 ? 'mid' : 'high')]),
    ];
    // Ordinary responses first, then the really-hard response if it is a different one.
    $letters = array_map('wr_letter', $q41);
    $q42Letter = wr_letter($q42);
    if (!in_array($q42Letter, $letters, true)) {
        $letters[] = $q42Letter;
    }
    foreach ($letters as $letter) {
        $key = '4.1.' . $letter;
        $s6[] = wr_h(WR_COPING_HEADINGS[$letter]);
        if (in_array($key, $q41, true) && $letter === $q42Letter) {
            $s6[] = wr_note('You chose this for when things get tough and for when things become especially difficult.');
        }
        $s6[] = wr_p($support['restricted'] && isset($c['restricted']['s6_' . $key]) ? $c['restricted']['s6_' . $key] : $c['s6']['coping'][$key]);
    }
    $s6[] = wr_h($l['s6_closing_heading']);
    $s6[] = wr_p($plain ? $c['s6']['closing']['neutral'] : $c['s6']['closing'][$primary]);
    $sections[6] = $s6;

    // 7 What's on your plate
    $areas = array_values(array_filter(wp_choices($answers, '1.4'), static fn($id) => is_string($id) && $id !== '1.4.k' && isset(WR_LIFE_AREA_PHRASES[wr_letter($id)])));
    $q12 = wp_int($answers, '1.2', 0, 10);
    $impact = str_replace('{n}', (string) $q12, $c['s7']['impact']);
    if ($areas !== []) {
        $list = wr_join(array_map(static fn($id) => WR_LIFE_AREA_PHRASES[wr_letter($id)], $areas));
        $opening = strtr($c['s7']['opening'], [
            '{areas}' => $list . (str_contains($list, ', and ') ? ',' : ''),
            '{isare}' => count($areas) === 1 ? 'is' : 'are',
        ]);
        $s7 = [wr_p($opening . ' ' . $impact)];
    } else {
        $s7 = [wr_p($impact)];
    }
    if (wp_recent_change($answers)) {
        $s7[] = wr_p($c['s7']['recent']);
    }
    $s7[] = wr_p($c['s7'][$q12 >= 8 ? 'impact_high' : ($q12 >= 4 ? 'impact_mid' : 'impact_low')]);
    foreach ($areas as $id) {
        $s7[] = wr_h($c['s7']['areas'][$id]['heading']);
        $s7[] = wr_p($c['s7']['areas'][$id]['text']);
    }
    $sections[7] = $s7;

    // 8 What helps you
    $s8 = [];
    if ($support['unsafe']) {
        $s8[] = wr_p($c['s8']['unsafe']);
        $s8[] = ['type' => 'links', 'items' => $c['s10']['urgent_links']];
    } elseif ($support['unavailable']) {
        $s8[] = wr_p($c['s8']['unavailable']);
    } else {
        $prefs = array_values(array_filter(wp_choices($answers, '5.1'), static fn($id) => is_string($id) && isset($c['s8']['prefs'][$id])));
        if ($prefs !== []) {
            $s8[] = wr_p(str_replace('{prefs}', wr_join(array_map(static fn($id) => WR_SUPPORT_PHRASES[wr_letter($id)], $prefs)), $c['s8']['opening']));
            foreach ($prefs as $id) {
                $s8[] = wr_h($c['s8']['prefs'][$id]['heading']);
                $s8[] = wr_p($c['s8']['prefs'][$id]['text']);
            }
        }
    }
    [$recharge, $settle] = wr_activity_groups($answers, $support['restricted']);
    $rechargeNames = ['alone' => 'time on your own', 'people' => 'time with people', 'mix' => 'a mix of both', 'depends' => 'it depends on the day'];
    $settleNames = ['movement' => 'moving your body', 'still' => 'being still and quiet', 'hands' => 'doing something with your hands', 'talking' => 'talking it through'];
    $s8[] = wr_h($c['s8']['recharge_heading'] . ': ' . $rechargeNames[$recharge]);
    $s8[] = wr_p($c['s8']['recharge'][$recharge]);
    $s8[] = wr_h($c['s8']['settle_heading'] . (isset($settleNames[$settle]) ? ': ' . $settleNames[$settle] : ''));
    $s8[] = wr_p($c['s8']['settle'][$settle]);
    $named = array_values(array_filter(
        wr_named_activities($answers),
        static fn($id) => !($support['restricted'] && in_array($id, ['6.5.b', '6.5.m'], true))
    ));
    if ($named !== []) {
        $s8[] = wr_h($l['s8_activities_heading']);
        foreach ($named as $id) {
            $s8[] = wr_h3(WR_ACTIVITIES[wr_letter($id)][0]);
            $s8[] = wr_p($c['s10']['step2'][$id]);
        }
        if ($activityEligible && count($named) > 1) {
            [, $phrase, $short] = WR_ACTIVITIES[wr_letter($activity)];
            $s8[] = wr_p(strtr($l['s8_most'], ['{activity}' => $phrase, '{short}' => $short]));
        }
    }
    $sections[8] = $s8;

    // 9 Your practical next steps (report-only launch copy)
    $s9 = [wr_p($l['s9']['opening'])];
    $goals = array_values(array_filter(array_keys(WR_GOAL_LABELS), static fn($id) => in_array($id, wp_choices($answers, '1.3'), true)));
    if ($goals !== []) {
        $s9[] = wr_h($l['s9']['goals_heading']);
        $s9[] = ['type' => 'list', 'items' => array_map(static fn($id) => WR_GOAL_LABELS[$id], $goals)];
    }
    if ($time !== null) {
        $s9[] = wr_p(str_replace('{time}', $time, $l['s9']['time']));
    }
    foreach ($l['s9']['blocks'] as [$heading, $text]) {
        $s9[] = wr_h($heading);
        $s9[] = wr_p($text);
    }
    $sections[9] = $s9;

    // 10 Your personal Tough-Day Guide
    $s10 = [wr_p($l['s10']['opening'])];
    $s10[] = wr_h($l['s10']['step1_heading']);
    $s10[] = wr_p($paired ? $c['s10']['step1'][$secondaryId] : $c['s10']['step1']['neutral']);
    if ($activity === null) {
        $s10[] = wr_h($l['s10']['step2_heading']);
        $s10[] = wr_p($c['s10']['step2_none']);
    } elseif (!$activityEligible) {
        $s10[] = wr_h($l['s10']['step2_heading']);
        $s10[] = wr_p($c['s10']['step2_contact_excluded']);
    } else {
        $s10[] = wr_h(str_replace('{short}', WR_ACTIVITIES[wr_letter($activity)][2], $l['s10']['step2_heading_named']));
        $s10[] = wr_p($c['s10']['step2'][$activity]);
    }
    if ($time !== null) {
        $s10[] = wr_p(str_replace('{time}', $time, $l['s10']['time']));
    }
    $s10[] = wr_h($l['s10']['step3_heading']);
    $s10[] = wr_p($support['restricted'] ? $c['restricted']['s10_step3'] : $c['s10']['step3']);
    $s10[] = wr_p($paired ? $c['s10']['closing'][$secondaryId] : $c['s10']['closing']['neutral']);
    $s10[] = wr_p($l['s10']['boundary']);
    $s10[] = wr_p($l['s10']['danger']);
    $s10[] = wr_p($l['s10']['crisis']);
    $links = [
        ['label' => 'Emergency: call 000', 'href' => 'tel:000'],
        ['label' => 'Lifeline: 13 11 14', 'href' => 'tel:131114'],
    ];
    if ($support['unsafe']) {
        $links[] = ['label' => '1800RESPECT: 1800 737 732', 'href' => 'tel:1800737732'];
    }
    $links[] = ['label' => 'More support options', 'href' => '/crisis-support.html'];
    $s10[] = ['type' => 'links', 'items' => $links];
    $sections[10] = $s10;

    // 11 Looking ahead (report-only launch copy)
    $s11 = [wr_p($l['s11']['opening']), wr_h($l['s11']['blocks1'][0]), wr_p($l['s11']['blocks1'][1]), wr_h($l['s11']['prefs_heading'])];
    if ($time !== null && $activityEligible) {
        $s11[] = wr_p(strtr($l['s11']['prefs'], ['{activity}' => WR_ACTIVITIES[wr_letter($activity)][1], '{time}' => $time]));
    } elseif ($time !== null) {
        $s11[] = wr_p("You chose {$time} as a manageable amount of time. That choice can be reconsidered if it no longer fits.");
    }
    $notifyAt = wr_notification_time($answers);
    $notify = (($answers['6.3a']['mode'] ?? null) === 'later') ? $l['s11']['notify_later'] . ' '
        : ($notifyAt !== null ? "You chose {$notifyAt} as a preferred time for general resource notifications. " : '');
    $s11[] = wr_p($notify . $l['s11']['notify_rest']);
    $s11[] = wr_h($l['s11']['blocks2'][0]);
    $s11[] = wr_p($l['s11']['blocks2'][1]);
    $sections[11] = $s11;

    // 12 About your report
    $sections[12] = array_map('wr_p', $c['s12']['paras']);

    ksort($sections);
    $out = [];
    foreach ($sections as $id => $blocks) {
        $out[] = [
            'id' => $id,
            'number' => $id,
            'group' => WR_GROUPS[$id],
            'title' => $id === 2 && $plain ? 'Understanding your responses' : WR_SECTION_TITLES[$id],
            'blocks' => $blocks,
        ];
    }

    return [
        'source' => $c['source'],
        'score_version' => WP_SCORE_VERSION,
        'language' => $plain ? 'plain' : 'characters',
        'primary' => ['id' => $primary, 'title' => WR_TITLES[$primary][$plain ? 1 : 0]],
        'support_first' => $support['unsafe'] ? [
            wr_p($c['s8']['unsafe']),
            wr_p($c['s10']['urgent'][0]),
            ['type' => 'links', 'items' => $c['s10']['urgent_links']],
        ] : null,
        'question' => $question,
        'sections' => $out,
        'section_count' => count($out),
    ];
}

/** Named helpful activities (6.5.a–m) in questionnaire order. */
function wr_named_activities(array $answers): array
{
    $chosen = wp_choices($answers, '6.5');
    return array_values(array_filter(
        array_map(static fn($l) => '6.5.' . $l, array_keys(WR_ACTIVITIES)),
        static fn($id) => in_array($id, $chosen, true)
    ));
}

/** The single most-helpful named activity: 6.5b, or the only named one ticked. */
function wr_most_helpful_activity(array $answers): ?string
{
    $named = wr_named_activities($answers);
    $chosen = wp_single($answers, '6.5b');
    if ($chosen !== null && in_array($chosen, $named, true)) {
        return $chosen;
    }
    return count($named) === 1 ? $named[0] : null;
}

/**
 * Recharge and settling versions (Appendix A mappings). Unsafe or unavailable support
 * removes Trusted person and Family from both mappings.
 * @return array{0: string, 1: string}
 */
function wr_activity_groups(array $answers, bool $restricted): array
{
    $eligible = array_values(array_filter(
        wr_named_activities($answers),
        static fn($id) => !($restricted && in_array($id, ['6.5.b', '6.5.m'], true))
    ));
    $letters = array_map('wr_letter', $eligible);

    $alone = array_intersect($letters, ['a', 'g', 'f', 'l']) !== [];
    $people = array_intersect($letters, ['b', 'm']) !== [];
    $recharge = $alone && $people ? 'mix' : ($alone ? 'alone' : ($people ? 'people' : 'depends'));

    $groups = ['movement' => ['c', 'd'], 'still' => ['g', 'l', 'a', 'e'], 'hands' => ['h', 'j', 'f'], 'talking' => ['b', 'm']];
    $settle = 'none';
    $most = wr_most_helpful_activity($answers);
    if ($most !== null && in_array($most, $eligible, true)) {
        foreach ($groups as $group => $members) {
            if (in_array(wr_letter($most), $members, true)) {
                $settle = $group;
            }
        }
    }
    if ($settle === 'none') {
        $counts = array_map(static fn($members) => count(array_intersect($letters, $members)), $groups);
        $max = max($counts);
        $leaders = array_keys($counts, $max, true);
        if ($max > 0 && count($leaders) === 1) {
            $settle = $leaders[0];
        }
    }
    return [$recharge, $settle];
}

