/** @return array{0: string, 1: string} [plain text, HTML] of the whole report */
function wr_report_email_bodies(array $report, ?string $fullName, string $reportUrl): array
{
    $h = static fn(string $s): string => htmlspecialchars($s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    $first = function_exists('extract_first_name') ? extract_first_name($fullName) : '';
    $greeting = $first !== '' ? "Hi {$first}," : 'Hi there,';
    $intro = 'Thank you for purchasing your Full Wellbeing Profile Report. Your report is below, and it is also saved to your Tools for the Tough Days account so you can come back to it at any time.';
    $pending = $report['question'] !== null
        ? 'Your report on the website includes a short question about a second description. Once you answer it there, your online report will update.'
        : null;
    $receipt = 'This was a one-time payment of $39.95 AUD. It is not a subscription, and you will not be charged again.';

    $text = [$greeting, '', $intro, '', 'View your report online (you may need to sign in): ' . $reportUrl, ''];
    $html = ['<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.55;color:#1d3536;max-width:640px">',
        '<p>' . $h($greeting) . '</p>', '<p>' . $h($intro) . '</p>',
        '<p><a href="' . $h($reportUrl) . '" style="display:inline-block;background:#26777B;color:#ffffff;padding:12px 22px;border-radius:8px;text-decoration:none;font-weight:600;">View your report online</a></p>'];
    if ($pending !== null) {
        $text[] = $pending;
        $text[] = '';
        $html[] = '<p>' . $h($pending) . '</p>';
    }

    $blocks = static function (array $blocks) use ($h, &$text, &$html): void {
        foreach ($blocks as $b) {
            switch ($b['type']) {
                case 'p':
                case 'note':
                    $text[] = $b['text'];
                    $text[] = '';
                    $html[] = '<p style="margin:0 0 12px' . ($b['type'] === 'note' ? ';color:#4a6566;font-style:italic' : '') . '">' . $h($b['text']) . '</p>';
                    break;
                case 'h':
                case 'h3':
                    $text[] = $b['text'];
                    $html[] = '<' . ($b['type'] === 'h' ? 'h3' : 'h4') . ' style="margin:18px 0 8px;color:#1a5558">' . $h($b['text']) . '</' . ($b['type'] === 'h' ? 'h3' : 'h4') . '>';
                    break;
                case 'list':
                    foreach ($b['items'] as $i) {
                        $text[] = '- ' . $i;
                    }
                    $text[] = '';
                    $html[] = '<ul style="margin:0 0 12px;padding-left:22px">' . implode('', array_map(static fn($i) => '<li>' . $h($i) . '</li>', $b['items'])) . '</ul>';
                    break;
                case 'table':
                    foreach ($b['rows'] as $r) {
                        $text[] = $r[0] . ': ' . $r[1];
                    }
                    $text[] = '';
                    $html[] = '<table style="border-collapse:collapse;width:100%;margin:0 0 14px;font-size:14px"><tr>'
                        . implode('', array_map(static fn($x) => '<th style="text-align:left;border-bottom:1px solid #cfe0e0;padding:6px">' . $h($x) . '</th>', $b['head'])) . '</tr>'
                        . implode('', array_map(static fn($r) => '<tr><td style="border-bottom:1px solid #e3eeee;padding:6px">' . $h($r[0]) . '</td><td style="border-bottom:1px solid #e3eeee;padding:6px">' . $h($r[1]) . '</td></tr>', $b['rows']))
                        . '</table>';
                    break;
                case 'links':
                    foreach ($b['items'] as $link) {
                        $text[] = $link['label'];
                    }
                    $text[] = '';
                    $html[] = '<p style="margin:0 0 12px">' . implode('<br>', array_map(static fn($link) => $h($link['label']), $b['items'])) . '</p>';
                    break;
            }
        }
    };

    $text[] = 'YOUR FULL WELLBEING PROFILE REPORT: ' . strtoupper($report['primary']['title']);
    $text[] = '';
    $html[] = '<h2 style="font-family:Georgia,serif;font-weight:400;color:#1a5558;margin:26px 0 4px">Your Full Wellbeing Profile Report</h2><p style="margin:0 0 18px;color:#4a6566">' . $h($report['primary']['title']) . '</p>';
    if ($report['support_first'] !== null) {
        $text[] = 'SUPPORT FIRST';
        $html[] = '<div style="background:#eef6f6;border-radius:8px;padding:12px 16px;margin:0 0 16px"><h3 style="margin:0 0 8px;color:#1a5558">Support first</h3>';
        $blocks($report['support_first']);
        $html[] = '</div>';
    }
    foreach ($report['sections'] as $s) {
        $text[] = $s['number'] . '. ' . strtoupper($s['title']);
        $text[] = '';
        $html[] = '<h2 style="font-family:Georgia,serif;font-weight:400;color:#1a5558;border-top:1px solid #cfe0e0;padding-top:18px;margin:26px 0 10px">' . $s['number'] . '. ' . $h($s['title']) . '</h2>';
        $blocks(array_values(array_filter($s['blocks'], static fn($b) => $b['type'] !== 'question')));
    }

    $text = array_merge($text, ['', $receipt, '', 'If you have any questions, just reply to this email.', '', 'Warm regards,', 'Nic Marcon', 'Registered Psychologist', 'Tools for the Tough Days', 'www.toolsforthetoughdays.com.au']);
    $html[] = '<p style="margin-top:26px">' . $h($receipt) . '</p><p>If you have any questions, just reply to this email.</p>'
        . '<p>Warm regards,<br>Nic Marcon<br>Registered Psychologist<br>Tools for the Tough Days<br>www.toolsforthetoughdays.com.au</p></div>';
    return [implode("\n", $text), implode("\n", $html)];
}

/** Email the whole report to the account address. Returns true when the mailer accepted it. */
function wr_email_report(array $run): bool
{
    require_once __DIR__ . '/mailer.php';
    $stmt = db()->prepare('SELECT email, full_name FROM users WHERE id = ?');
    $stmt->execute([(int) $run['user_id']]);
    $user = $stmt->fetch();
    if (!$user) {
        return false;
    }
    $siteUrl = defined('SITE_URL') ? rtrim((string) SITE_URL, '/') : 'https://www.toolsforthetoughdays.com.au';
    [$text, $html] = wr_report_email_bodies(wr_report_for_run($run), $user['full_name'] ?? null, $siteUrl . '/wellbeing-profile.html?view=report');
    $sent = send_transactional_email((string) $user['email'], 'Your Full Wellbeing Profile Report', $text, $html);
    if ($sent) {
        db()->prepare('UPDATE wellbeing_profile_runs SET report_emailed_at = NOW() WHERE id = ?')->execute([(int) $run['id']]);
    }
    return $sent;
}

// ─────────────────────────────────────────────────────────────────────────────
// Saved runs and purchases (database)
// ─────────────────────────────────────────────────────────────────────────────

function wr_ensure_table(): void
{
    static $done = false;
    if ($done) {
        return;
    }
    db()->exec(
        "CREATE TABLE IF NOT EXISTS wellbeing_profile_runs (
            id                         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
            user_id                    INT UNSIGNED    NOT NULL,
            answers_json               TEXT            NOT NULL,
            score_version              VARCHAR(64)     NOT NULL,
            accepted_primary           VARCHAR(4)      NOT NULL,
            language                   ENUM('characters','plain') NOT NULL DEFAULT 'characters',
            secondary_selected         VARCHAR(4)          NULL DEFAULT NULL,
            secondary_response         VARCHAR(16)         NULL DEFAULT NULL,
            secondary_answered_at      DATETIME            NULL DEFAULT NULL,
            stripe_checkout_session_id VARCHAR(128)        NULL DEFAULT NULL,
            stripe_payment_intent_id   VARCHAR(64)         NULL DEFAULT NULL,
            amount_cents               INT UNSIGNED        NULL DEFAULT NULL,
            currency                   CHAR(3)             NULL DEFAULT NULL,
            purchased_at               DATETIME            NULL DEFAULT NULL,
            report_emailed_at          DATETIME            NULL DEFAULT NULL,
            created_at                 DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
            updated_at                 DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            UNIQUE KEY uq_wpr_checkout_session (stripe_checkout_session_id),
            KEY idx_wpr_user_purchased (user_id, purchased_at),
            KEY idx_wpr_unpurchased (purchased_at, created_at),
            CONSTRAINT fk_wpr_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
    );
    $done = true;
}

/** Keep only the answers the report needs, with simple shape checks. */
function wr_clean_answers(array $answers): array
{
    $clean = [];
    foreach (WR_STORED_QUESTIONS as $id) {
        if (!array_key_exists($id, $answers)) {
            continue;
        }
        $v = $answers[$id];
        if ($id === '6.3a') {
            // Notification time preference: {mode: later} or {mode: time, time: "HH:MM", timezone}
            if (is_array($v) && ($v['mode'] ?? '') === 'later') {
                $clean[$id] = ['mode' => 'later'];
            } elseif (is_array($v) && ($v['mode'] ?? '') === 'time' && preg_match('/^([01]\d|2[0-3]):[0-5]\d$/', (string) ($v['time'] ?? ''))) {
                $clean[$id] = ['mode' => 'time', 'time' => $v['time'], 'timezone' => isset(WR_ZONES[$v['timezone'] ?? '']) ? $v['timezone'] : null];
            }
            continue;
        }
        if (is_array($v)) {
            $v = array_values(array_filter($v, static fn($x) => is_string($x) && strlen($x) <= 12));
        } elseif (!is_int($v) && !(is_string($v) && strlen($v) <= 12)) {
            continue;
        }
        $clean[$id] = $v;
    }
    return $clean;
}

/**
 * Score the answers again on the server and save a run for the buyer to pay for.
 * The accepted primary must be one the answers allow. Throws WellbeingScoringError.
 */
function wr_save_run(int $userId, array $answers, string $acceptedPrimary, string $language, bool $safetyConfirmed): int
{
    $answers = wr_clean_answers($answers);
    $result = wp_score_questionnaire($answers);
    if ($result['safety']['safety_check_required'] && !$safetyConfirmed) {
        throw new WellbeingScoringError('The safety check needs to be answered first.');
    }
    $selection = wp_select_primary($result['primary'], $acceptedPrimary, $language);
    if ($selection['status'] !== 'accepted') {
        throw new WellbeingScoringError('The full report needs a description you have confirmed.');
    }

    wr_ensure_table();
    // Non-buyers' answers are not kept (master §12).
    db()->exec('DELETE FROM wellbeing_profile_runs WHERE purchased_at IS NULL AND created_at < DATE_SUB(NOW(), INTERVAL ' . WR_UNPURCHASED_RETENTION_DAYS . ' DAY)');

    db()->prepare(
        'INSERT INTO wellbeing_profile_runs (user_id, answers_json, score_version, accepted_primary, language)
         VALUES (?, ?, ?, ?, ?)'
    )->execute([$userId, json_encode($answers), WP_SCORE_VERSION, $acceptedPrimary, $language]);
    return (int) db()->lastInsertId();
}

function wr_find_run(int $runId, int $userId): ?array
{
    wr_ensure_table();
    $stmt = db()->prepare('SELECT * FROM wellbeing_profile_runs WHERE id = ? AND user_id = ?');
    $stmt->execute([$runId, $userId]);
    return $stmt->fetch() ?: null;
}

function wr_latest_purchased_run(int $userId): ?array
{
    wr_ensure_table();
    $stmt = db()->prepare('SELECT * FROM wellbeing_profile_runs WHERE user_id = ? AND purchased_at IS NOT NULL ORDER BY purchased_at DESC, id DESC LIMIT 1');
    $stmt->execute([$userId]);
    return $stmt->fetch() ?: null;
}

function wr_report_for_run(array $run): array
{
    $report = wr_build_report(
        json_decode((string) $run['answers_json'], true) ?: [],
        (string) $run['accepted_primary'],
        (string) $run['language'],
        $run['secondary_selected'] ?: null,
        $run['secondary_response'] ?: null
    );
    $report['run_id'] = (int) $run['id'];
    $report['purchased_at'] = $run['purchased_at'];
    $report['emailed_at'] = $run['report_emailed_at'] ?? null;
    return $report;
}

function wr_save_secondary_answer(array $run, ?string $selected, string $response): void
{
    $answers = json_decode((string) $run['answers_json'], true) ?: [];
    $state = wr_secondary_state($answers, (string) $run['accepted_primary'], $run['secondary_selected'] ?: null, $run['secondary_response'] ?: null);
    wr_validate_secondary_answer($state, $selected, $response);
    db()->prepare(
        'UPDATE wellbeing_profile_runs SET secondary_selected = ?, secondary_response = ?, secondary_answered_at = NOW()
         WHERE id = ? AND secondary_response IS NULL'
    )->execute([$selected, $response, (int) $run['id']]);
}

function wr_save_language(array $run, string $language): void
{
    if (!in_array($language, ['characters', 'plain'], true)) {
        throw new WellbeingScoringError('Language preference must be "characters" or "plain".');
    }
    db()->prepare('UPDATE wellbeing_profile_runs SET language = ? WHERE id = ?')->execute([$language, (int) $run['id']]);
}

/** Has this account paid access to the resource library (a Stripe subscription that is current)? */
function wr_has_resource_access(int $userId): bool
{
    $stmt = db()->prepare(
        "SELECT 1 FROM subscriptions
         WHERE user_id = ? AND stripe_subscription_id IS NOT NULL
           AND status IN ('active', 'trialing', 'past_due')
           AND (current_period_end IS NULL OR current_period_end > NOW())
         LIMIT 1"
    );
    $stmt->execute([$userId]);
    return (bool) $stmt->fetchColumn();
}

/**
 * Record a paid report and email a copy. Idempotent (webhook retries, and the return page may get
 * there first): only the call that marks it paid sends the email.
 * @return bool true when this call marked it paid
 */
function wr_mark_paid(int $runId, int $userId, string $checkoutSessionId, ?string $paymentIntentId, int $amountCents, string $currency): bool
{
    wr_ensure_table();
    $pdo = db();
    $pdo->beginTransaction();
    try {
        $stmt = $pdo->prepare('SELECT id, purchased_at FROM wellbeing_profile_runs WHERE id = ? AND user_id = ? FOR UPDATE');
        $stmt->execute([$runId, $userId]);
        $run = $stmt->fetch();
        if (!$run) {
            $pdo->rollBack();
            error_log("wellbeing report: paid session {$checkoutSessionId} names run {$runId}, which user {$userId} does not have");
            return false;
        }
        if ($run['purchased_at'] !== null) {
            $pdo->commit();
            return false;
        }
        $pdo->prepare(
            'UPDATE wellbeing_profile_runs
             SET purchased_at = NOW(), stripe_checkout_session_id = ?, stripe_payment_intent_id = ?, amount_cents = ?, currency = ?
             WHERE id = ?'
        )->execute([$checkoutSessionId, $paymentIntentId, $amountCents, strtolower($currency), $runId]);
        // One-off payments create no invoice, so record the payment here for billing history.
        $pdo->prepare(
            "INSERT INTO payments (user_id, subscription_id, stripe_payment_intent_id, amount_cents, currency, status, description)
             VALUES (?, NULL, ?, ?, ?, 'succeeded', ?)
             ON DUPLICATE KEY UPDATE status = VALUES(status)"
        )->execute([$userId, $paymentIntentId, $amountCents, strtolower($currency), WR_PRODUCT_NAME]);
        $pdo->commit();
    } catch (Throwable $e) {
        $pdo->rollBack();
        throw $e;
    }

    // Access never depends on the email: a failure is logged and the buyer can resend from the page.
    try {
        $saved = wr_find_run($runId, $userId);
        if ($saved && !wr_email_report($saved)) {
            error_log("wellbeing report email not sent for run {$runId}");
        }
    } catch (Throwable $e) {
        error_log('wellbeing report email failed for user ' . $userId . ': ' . $e->getMessage());
    }
    return true;
}

/**
 * Check a Checkout Session for this product and record the purchase if it is paid.
 * Used by the webhook and by the page the buyer returns to (which looks the session up at Stripe,
 * so a visit to the return URL alone is never treated as proof of payment).
 * @return ?int the run id, or null when the session is not a paid report for this user
 */
function wr_confirm_checkout_session(object $session, int $userId): ?int
{
    $meta = $session->metadata ?? null;
    $productKey = (string) ($meta['product_key'] ?? '');
    $metaUser = (int) ($meta['user_id'] ?? 0);
    $runId = (int) ($meta['run_id'] ?? 0);
    if ($productKey !== WR_PRODUCT_KEY || $metaUser !== $userId || $runId <= 0) {
        return null;
    }
    if (($session->mode ?? '') !== 'payment' || ($session->payment_status ?? '') !== 'paid') {
        return null;
    }
    wr_mark_paid(
        $runId,
        $userId,
        (string) $session->id,
        is_string($session->payment_intent ?? null) ? $session->payment_intent : null,
        (int) ($session->amount_total ?? WR_PRICE_CENTS),
        (string) ($session->currency ?? 'aud')
    );
    return $runId;
}
